INSERT INTO public.flashcards
  (id1, cn, pinyin, vocabulary, pinyin_vocab, th, sentence_test, translate, pinyin_sentence)
VALUES
(951, '战', 'zhàn', '战争', 'zhàn zhēng', 'สงคราม', '战争中，苦难的人们流离失所。', 'ในสงคราม ผู้คนที่ทุกข์ยากต้องพลัดที่อยู่ไร้ที่พึ่ง', 'zhàn zhēng zhōng, kǔ nàn de rén men liú lí shī suǒ'),
(952, '命', 'mìng', '命令', 'mìng lìng', 'คำสั่ง', '士兵要无条件听从将军的命令。', 'ทหารต้องเชื่อฟังคำสั่งของแม่ทัพอย่างไม่มีเงื่อนไข', 'shì bīng yào wú tiáo jiàn tīng cóng jiāng jūn de mìng lìng'),
(953, '枪', 'qiāng', '枪声', 'qiāng shēng', 'เสียงปืน', '战士们在熟睡中被枪声惊醒了。', 'เหล่านักรบถูกเสียงปืนปลุกให้ตื่นขึ้นกลางดึก', 'zhàn shì men zài shú shuì zhōng bèi qiāng shēng jīng xǐng le'),
(954, '突', 'tū', '突然', 'tū rán', 'ทันใดนั้น/อยู่ๆ', '一只小狗突然从山洞中跑了出来。', 'จู่ๆ ก็มีสุนัขน้อยตัวหนึ่งวิ่งออกมาจากถ้ำ', 'yì zhī xiǎo gǒu tū rán cóng shān dòng zhōng pǎo le chū lái'),
(955, '丢', 'diū', '丢掉', 'diū diào', 'ทิ้ง/ทำหล่นหาย', '坏人在慌乱中丢掉了自己的行李。', 'คนร้ายทำสัมภาระของตัวเองหล่นหายไปในความชุลมุน', 'huài rén zài huāng luàn zhōng diū diào le zì jǐ de xíng li'),
(956, '咬', 'yǎo', '咬人', 'yǎo rén', 'กัด (คน)', '小心！狗生气的时候会咬人的。', 'ระวัง! เวลาหมาโกรธมันกัดคนได้นะ', 'xiǎo xīn! gǒu shēng qì de shí hòu huì yǎo rén de'),
(957, '夹', 'jiā', '夹子', 'jiā zi', 'ที่หนีบ/คลิป', '用夹子把这几张作业纸夹住吧。', 'เอาที่หนีบมาหนีบกระดาษการบ้านพวกนี้ไว้เถอะ', 'yòng jiā zi bǎ zhè jǐ zhāng zuò yè zhǐ jiā zhù ba'),
(958, '质', 'zhì', '变质', 'biàn zhì', 'เสีย/เน่าเสีย (คุณภาพเปลี่ยน)', '这些食物已经变质了，不能吃了。', 'อาหารพวกนี้เสียแล้ว กินไม่ได้แล้ว', 'zhè xiē shí wù yǐ jīng biàn zhì le, bù néng chī le'),
(959, '式', 'shì', '样式', 'yàng shì', 'รูปแบบ/แบบ', '广场上展出了各种样式的花灯。', 'ที่ลานกว้างมีการจัดแสดงโคมไฟหลากหลายรูปแบบ', 'guǎng chǎng shàng zhǎn chū le gè zhǒng yàng shì de huā dēng'),
(960, '助', 'zhù', '帮助', 'bāng zhù', 'ช่วยเหลือ', '朋友遇到了困难，我要去帮助他。', 'เพื่อนเจอปัญหา ฉันต้องไปช่วยเขา', 'péng yǒu yù dào le kùn nán, wǒ yào qù bāng zhù tā'),
(961, '漂', 'piāo', '漂浮', 'piāo fú', 'ลอย', '一叶小舟静静地漂浮在水面上。', 'เรือน้อยลำหนึ่งลอยนิ่งอยู่บนผิวน้ำ', 'yí yè xiǎo zhōu jìng jìng de piāo fú zài shuǐ miàn shàng'),
(962, '泊', 'bó', '停泊', 'tíng bó', 'จอดเทียบ (เรือ)', '一艘小白船静静地停泊在湖边。', 'เรือสีขาวลำน้อยจอดนิ่งอยู่ริมทะเลสาบ', 'yì sōu xiǎo bái chuán jìng jìng de tíng bó zài hú biān'),
(963, '漫', 'màn', '漫出', 'màn chū', 'ล้น/เอ่อล้น', '盆子里的水太满了，小心漫出来。', 'น้ำในกะละมังเต็มเกินไป ระวังล้นออกมา', 'pén zi lǐ de shuǐ tài mǎn le, xiǎo xīn màn chū lái'),
(964, '刚', 'gāng', '金刚石', 'jīn gāng shí', 'เพชร', '金刚石有各种不同的颜色。', 'เพชรมีสีสันหลากหลายแตกต่างกัน', 'jīn gāng shí yǒu gè zhǒng bù tóng de yán sè'),
(965, '糟', 'zāo', '米糟', 'mǐ zāo', 'กากข้าวหมัก', '糟糕！米糟坏了，不能吃了。', 'แย่แล้ว! กากข้าวหมักเสียแล้ว กินไม่ได้แล้ว', 'zāo gāo! mǐ zāo huài le, bù néng chī le'),
(966, '假', 'jiǎ', '假牙', 'jiǎ yá', 'ฟันปลอม', '爷爷的假牙看起来跟真的一样。', 'ฟันปลอมของคุณปู่ดูเหมือนฟันจริงเลย', 'yé ye de jiǎ yá kàn qǐ lái gēn zhēn de yí yàng'),
(967, '钢', 'gāng', '钢板', 'gāng bǎn', 'แผ่นเหล็กกล้า', '家里的大门是用钢板做的。', 'ประตูใหญ่ของบ้านทำจากแผ่นเหล็กกล้า', 'jiā lǐ de dà mén shì yòng gāng bǎn zuò de'),
(968, '将', 'jiāng', '将军', 'jiāng jūn', 'แม่ทัพ/นายพล', '将军带领士兵们展开了英勇的战斗。', 'แม่ทัพนำทหารเปิดศึกอย่างกล้าหาญ', 'jiāng jūn dài lǐng shì bīng men zhǎn kāi le yīng yǒng de zhàn dòu'),
(969, '俩', 'liǎ', '兄弟俩', 'xiōng dì liǎ', 'สองพี่น้อง', '兄弟俩感情很好，每天都在一起。', 'สองพี่น้องรักกันดี อยู่ด้วยกันทุกวัน', 'xiōng dì liǎ gǎn qíng hěn hǎo, měi tiān dōu zài yì qǐ'),
(970, '哇', 'wā', '哇哇哭', 'wā wā kū', 'ร้องไห้จ้า', '宝宝在小推车里哇哇哭起来。', 'เจ้าหนูร้องไห้จ้าขึ้นมาในรถเข็น', 'bǎo bao zài xiǎo tuī chē lǐ wā wā kū qǐ lái'),
(971, '贫', 'pín', '贫穷', 'pín qióng', 'ยากจน', '大山深处有一个贫穷落后的小山村。', 'ลึกเข้าไปในภูเขามีหมู่บ้านเล็กๆ ที่ยากจนล้าหลัง', 'dà shān shēn chù yǒu yí gè pín qióng luò hòu de xiǎo shān cūn'),
(972, '饱', 'bǎo', '吃饱', 'chī bǎo', 'อิ่ม', '小懒猫吃饱喝足后，倒头就睡了。', 'เจ้าแมวขี้เกียจกินอิ่มดื่มพอแล้วก็ล้มตัวนอนหลับ', 'xiǎo lǎn māo chī bǎo hē zú hòu, dǎo tóu jiù shuì le'),
(973, '饥', 'jī', '饥饿', 'jī è', 'หิวโหย', '一只饥饿的老虎正在寻找食物。', 'เสือหิวโหยตัวหนึ่งกำลังออกหาอาหาร', 'yì zhī jī è de lǎo hǔ zhèng zài xún zhǎo shí wù'),
(974, '族', 'zú', '民族', 'mín zú', 'ชนชาติ/ชาติพันธุ์', '中国一共有五十六个民族。', 'ประเทศจีนมีชนชาติทั้งหมดห้าสิบหกชนชาติ', 'zhōng guó yí gòng yǒu wǔ shí liù gè mín zú'),
(975, '孙', 'sūn', '孙子', 'sūn zi', 'หลาน (ชาย)', '爷爷每天都抱着小孙子去外面玩。', 'คุณปู่อุ้มหลานชายตัวน้อยออกไปเล่นข้างนอกทุกวัน', 'yé ye měi tiān dōu bào zhe xiǎo sūn zi qù wài miàn wán'),
(976, '祖', 'zǔ', '祖国', 'zǔ guó', 'มาตุภูมิ', '每个人都深深热爱着自己的祖国。', 'ทุกคนต่างรักมาตุภูมิของตนอย่างสุดซึ้ง', 'měi gè rén dōu shēn shēn rè ài zhe zì jǐ de zǔ guó'),
(977, '密', 'mì', '密室', 'mì shì', 'ห้องลับ', '那座山上有一个装满宝贝的密室。', 'บนภูเขาลูกนั้นมีห้องลับที่เต็มไปด้วยสมบัติ', 'nà zuò shān shàng yǒu yí gè zhuāng mǎn bǎo bèi de mì shì'),
(978, '炉', 'lú', '火炉', 'huǒ lú', 'เตาไฟ', '一家人围坐在火炉旁，有说有笑。', 'คนทั้งครอบครัวนั่งล้อมเตาไฟ พูดคุยหัวเราะกัน', 'yì jiā rén wéi zuò zài huǒ lú páng, yǒu shuō yǒu xiào'),
(979, '冈', 'gāng', '井冈山', 'jǐng gāng shān', 'ภูเขาจิ่งกัง (สถานที่)', '他的家乡在井冈山。', 'บ้านเกิดของเขาอยู่ที่ภูเขาจิ่งกัง', 'tā de jiā xiāng zài jǐng gāng shān'),
(980, '牢', 'láo', '坐牢', 'zuò láo', 'ติดคุก', '她每天被关在屋里，好像坐牢一样。', 'เธอถูกขังอยู่ในห้องทุกวัน เหมือนติดคุกเลย', 'tā měi tiān bèi guān zài wū lǐ, hǎo xiàng zuò láo yí yàng'),
(981, '容', 'róng', '容纳', 'róng nà', 'จุ/รองรับ', '这个会议室可以容纳一百多人。', 'ห้องประชุมนี้จุคนได้ร้อยกว่าคน', 'zhè ge huì yì shì kě yǐ róng nà yì bǎi duō rén'),
(982, '易', 'yì', '容易', 'róng yì', 'ง่าย', '很多事情说起来容易，做起来难。', 'หลายเรื่องพูดง่ายแต่ทำยาก', 'hěn duō shì qíng shuō qǐ lái róng yì, zuò qǐ lái nán'),
(983, '死', 'sǐ', '死亡', 'sǐ wáng', 'ความตาย', '所有的生命有一天都要面对死亡。', 'ทุกชีวิตสักวันหนึ่งต้องเผชิญกับความตาย', 'suǒ yǒu de shēng mìng yǒu yì tiān dōu yào miàn duì sǐ wáng'),
(984, '特', 'tè', '特别', 'tè bié', 'พิเศษ', '我为她准备了一份特别的礼物。', 'ฉันเตรียมของขวัญพิเศษไว้ให้เธอชิ้นหนึ่ง', 'wǒ wèi tā zhǔn bèi le yí fèn tè bié de lǐ wù'),
(985, '希', 'xī', '希望', 'xī wàng', 'ความหวัง', '少年儿童是祖国的未来和希望。', 'เด็กและเยาวชนคืออนาคตและความหวังของชาติ', 'shào nián ér tóng shì zǔ guó de wèi lái hé xī wàng'),
(986, '其', 'qí', '其中', 'qí zhōng', 'ในนั้น/ในบรรดา', '前面有三座楼，其中一座是商场。', 'ข้างหน้ามีตึกสามหลัง ในนั้นหลังหนึ่งเป็นห้างสรรพสินค้า', 'qián miàn yǒu sān zuò lóu, qí zhōng yí zuò shì shāng chǎng'),
(987, '弹', 'tán', '弹力', 'tán lì', 'แรงยืดหยุ่น', '这张弓的弹力很大，要小心。', 'คันธนูนี้มีแรงดีดมาก ต้องระวัง', 'zhè zhāng gōng de tán lì hěn dà, yào xiǎo xīn'),
(988, '打', 'dǎ', '打扮', 'dǎ bàn', 'แต่งตัว', '舞会上每个人都打扮得很漂亮。', 'ในงานเต้นรำ ทุกคนแต่งตัวสวยงามกันหมด', 'wǔ huì shàng měi gè rén dōu dǎ bàn de hěn piào liang'),
(989, '哨', 'shào', '口哨', 'kǒu shào', 'ผิวปาก/เสียงนกหวีด', '他得意洋洋地吹着口哨回家了。', 'เขาผิวปากอย่างภาคภูมิใจกลับบ้านไป', 'tā dé yì yáng yáng de chuī zhe kǒu shào huí jiā le'),
(990, '并', 'bìng', '并排', 'bìng pái', 'เรียงเคียงข้าง', '那两个人并排坐着，谁也不说话。', 'สองคนนั้นนั่งเรียงเคียงข้างกัน ไม่มีใครพูดสักคำ', 'nà liǎng gè rén bìng pái zuò zhe, shéi yě bù shuō huà'),
(991, '芬', 'fēn', '芬芳', 'fēn fāng', 'หอมกรุ่น', '花朵的芬芳引来一群飞舞的蝴蝶。', 'กลิ่นหอมของดอกไม้ดึงดูดฝูงผีเสื้อให้บินร่ายรำมา', 'huā duǒ de fēn fāng yǐn lái yì qún fēi wǔ de hú dié'),
(992, '芳', 'fāng', '芳香', 'fāng xiāng', 'หอมหวน', '百合花开了，散发出阵阵芳香。', 'ดอกลิลลี่บานส่งกลิ่นหอมหวนออกมาเป็นระลอก', 'bǎi hé huā kāi le, sàn fā chū zhèn zhèn fāng xiāng'),
(993, '栽', 'zāi', '栽树', 'zāi shù', 'ปลูกต้นไม้', '前人栽树，后人乘凉。', 'คนรุ่นก่อนปลูกต้นไม้ คนรุ่นหลังได้ร่มเงา', 'qián rén zāi shù, hòu rén chéng liáng'),
(994, '独', 'dú', '独自', 'dú zì', 'ตามลำพัง/คนเดียว', '她常常独自一人在花园里散步。', 'เธอมักเดินเล่นอยู่ในสวนตามลำพังคนเดียว', 'tā cháng cháng dú zì yì rén zài huā yuán lǐ sàn bù'),
(995, '弱', 'ruò', '虚弱', 'xū ruò', 'อ่อนแอ/อ่อนเพลีย', '她刚大病了一场，身体还很虚弱。', 'เธอเพิ่งป่วยหนักมา ร่างกายยังอ่อนเพลียอยู่', 'tā gāng dà bìng le yì chǎng, shēn tǐ hái hěn xū ruò'),
(996, '拐', 'guǎi', '拐杖', 'guǎi zhàng', 'ไม้เท้า', '他的腿伤好了，可以丢掉拐杖了。', 'ขาของเขาหายดีแล้ว ทิ้งไม้เท้าได้แล้ว', 'tā de tuǐ shāng hǎo le, kě yǐ diū diào guǎi zhàng le'),
(997, '治', 'zhì', '治病', 'zhì bìng', 'รักษาโรค', '医生们正在忙着治病救人。', 'เหล่าหมอกำลังยุ่งอยู่กับการรักษาโรคช่วยชีวิตคน', 'yī shēng men zhèng zài máng zhe zhì bìng jiù rén'),
(998, '阵', 'zhèn', '阵地', 'zhèn dì', 'แนวรบ/ฐานที่มั่น', '我们今夜一定要赶到前方阵地。', 'คืนนี้พวกเราต้องรีบไปให้ถึงแนวรบข้างหน้าให้ได้', 'wǒ men jīn yè yí dìng yào gǎn dào qián fāng zhèn dì'),
(999, '寿', 'shòu', '长寿', 'cháng shòu', 'อายุยืน', '那个村子的老人们都很长寿。', 'ผู้เฒ่าในหมู่บ้านนั้นล้วนอายุยืนกันทั้งนั้น', 'nà ge cūn zi de lǎo rén men dōu hěn cháng shòu'),
(1000, '宜', 'yí', '便宜', 'pián yi', 'ถูก (ราคา)', '这家饭店的东西又便宜又好吃。', 'อาหารร้านนี้ทั้งถูกทั้งอร่อย', 'zhè jiā fàn diàn de dōng xi yòu pián yi yòu hǎo chī');
